const db = require("./db");

// Resolves the session cookie to its user and account. Every request that
// reaches a route handler has passed through here.
async function sessionUser(req, res, next) {
  const rows = await db.query(
    "SELECT u.id, u.email, u.account_id FROM sessions s JOIN users u ON u.id = s.user_id JOIN accounts a ON a.id = u.account_id WHERE s.token = $1 AND s.expires_at > now() AND a.deleted_at IS NULL",
    [req.cookies && req.cookies.session]
  );
  if (!rows.length) return res.status(401).end();
  req.user = { id: rows[0].id, email: rows[0].email, accountId: rows[0].account_id };
  next();
}

module.exports = { sessionUser };

logging.js.text:
// Logs one JSON line per completed request. Bodies and cookies are left out
// because they carry billing emails and session tokens.
function requestLog(req, res, next) {
  const start = process.hrtime.bigint();
  res.on("finish", () => {
    console.log(JSON.stringify({
      method: req.method,
      path: req.originalUrl,
      status: res.statusCode,
      ms: Number(process.hrtime.bigint() - start) / 1e6,
      userId: req.user && req.user.id,
      accountId: req.user && req.user.accountId,
    }));
  });
  next();
}

module.exports = { requestLog };

