const express = require("express");
const { sessionUser } = require("./auth");
const accounts = require("./routes/accounts");
const orders = require("./routes/orders");

const app = express();
app.use(express.json());

// Logs one line per request when the response finishes or the client goes
// away. Registered before sessionUser so rejected requests are logged too;
// req.user is read at close time, after sessionUser has set it.
app.use((req, res, next) => {
  const start = process.hrtime.bigint();
  res.on("close", () => {
    console.log(JSON.stringify({
      method: req.method,
      path: req.originalUrl,
      status: res.writableFinished ? res.statusCode : "aborted",
      ms: Number(process.hrtime.bigint() - start) / 1e6,
      userId: req.user && req.user.id,
      accountId: req.user && req.user.accountId,
    }));
  });
  next();
});

// Resolves the session cookie to a user row and sets req.user for every
// request; requests without a valid session are rejected here.
app.use(sessionUser);

app.use("/accounts", accounts);
app.use("/orders", orders);

app.listen(process.env.PORT || 3000);

