// Writes one JSON line per request once the response closes, including
// requests rejected by sessionUser and requests the client abandoned. Bodies,
// cookies, and email addresses are deliberately left out.
function requestLogger(req, res, next) {
  const start = process.hrtime.bigint();
  res.on("close", () => {
    console.log(JSON.stringify({
      time: new Date().toISOString(),
      method: req.method,
      path: req.originalUrl,
      status: res.statusCode,
