const express = require("express");
const db = require("../db");

const router = express.Router();

// Clients may send an Idempotency-Key header so that a retry (after a timeout
// or a dropped connection) returns the original order instead of creating a
// second one. Keys are unique per account; the key is stored on the order row,
// so it is recorded in the same statement that creates the order.
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key") || null;
  if (key && key.length > 255) return res.status(400).end();

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) ON CONFLICT (account_id, idempotency_key) DO NOTHING RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, key]
  );
  if (row) return res.status(201).json(row);

  // The key was already used. Replay that order, unless this request asks for
  // a different one.
  const [existing] = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, key]
  );
  if (existing.sku !== req.body.sku || String(existing.quantity) !== String(req.body.quantity)) {
    return res.status(422).end();
  }
  res.set("Idempotent-Replayed", "true").status(201).json(existing);
});

// Scoped to the caller's account; another account's order id gets a 404.
router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

turns.text:
I added a single middleware rather than logging in each route. It's in the new file `log.js`, and `app.js` registers it before `sessionUser`, so requests rejected with 401 are logged too. Each request produces one JSON line with:

- the method, path and status;
- `completed`, which is false when no response was sent;
- the duration in milliseconds;
- the user and account ids, or null when there's no session.

The line is written on the response's `close` event rather than `finish`, so requests that never get a response are still logged, with `status: null`. Request bodies and cookies aren't logged, because they contain billing emails and session tokens.

I tested the middleware in a small Express app separate from this repository, with a successful request, a 401, and a request the client abandoned. All three produced the expected line.

One gap remains: when a dropped database connection crashes the process (the case from your last question), the process exits before `close` fires. The requests in flight at that moment won't be logged.

