// Logs one JSON line per request when its response closes. "completed" is
// false when the connection closed before a response was fully sent. Bodies
// and cookies are never logged: they carry billing emails and session tokens.
function requestLog(req, res, next) {
  const start = process.hrtime.bigint();
  res.on("close", () => {
    console.log(JSON.stringify({
      method: req.method,
      path: req.originalUrl,
      status: res.statusCode,
      completed: res.writableFinished,
      ms: Number(process.hrtime.bigint() - start) / 1e6,
      userId: req.user && req.user.id,
      accountId: req.user && req.user.accountId,
    }));
  });
  next();
}

