// and returns 404, the same as an id that does not exist.
router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

turns.text:
I added request logging as a single middleware in `logging.js`, registered first in `app.js`. It covers every route, including requests that auth rejects with a 401.

When each response closes, it prints one JSON line with the method, path, status, duration, user id and account id. It reads the user at close time, so `sessionUser` has already set it by then. It never logs request bodies or cookies, because those carry session tokens and billing emails. If the client disconnects before getting a response, the line has `"aborted": true` and a null status.

I tested it in a scratch Express app using a stub in place of `sessionUser`, since the project's dependencies aren't installed:

```
{"method":"PATCH","path":"/orders/5/cancel","status":401,"aborted":false,"ms":2,"userId":null,"accountId":null}
{"method":"PATCH","path":"/orders/5/cancel","status":200,"aborted":false,"ms":3,"userId":7,"accountId":3}
{"method":"POST","path":"/orders","status":404,"aborted":false,"ms":7,"userId":7,"accountId":3}
{"method":"GET","path":"/orders/slow","status":null,"aborted":true,"ms":51,"userId":7,"accountId":3}
```

There's one gap: requests that are still running when the process crashes are never logged. That includes the dropped-connection crash in `write()`.

