// One JSON line per request. Logged on "close" rather than "finish" so
// requests the client abandons, or that never get a response, still appear.
// Bodies and cookies are deliberately left out: they carry billing emails and
// session tokens.
function requestLog(req, res, next) {
  const start = process.hrtime.bigint();
  res.on("close", () => {
    console.log(JSON.stringify({
      method: req.method,
      path: req.originalUrl,
      status: res.statusCode,
      completed: res.writableFinished,
      ms: Number(process.hrtime.bigint() - start) / 1e6,
      userId: req.user ? req.user.id : null,
      accountId: req.user ? req.user.accountId : null,
    }));
  });
  next();
}

module.exports = { requestLog };

